const brands = [{"name":"Avni Wellness","key":"avni","short":"AW","fy25":2.85,"fy26":7.11,"fy27":11,"growth":54.71,"gm":23,"ebitda":-0.09,"ebitdaMargin":-1.3,"multiple":4,"valuation":28.46,"bubble":"b1","totalRevenue":20.96,"logo_file":"logo_avni.txt","logo":"assets/brand-images/avni_image.webp","founders":[{"name":"Sujata Pawar","photo":"data:image/jpeg;base64,"},{"name":"Apurv Agrawal","photo":"data:image/jpeg;base64,"}]},{"name":"BhadePay","key":"bhadepay","short":"BP","fy25":5.3,"fy26":5.13,"fy27":8.3,"growth":61.79,"gm":100,"ebitda":0.76,"ebitdaMargin":14.7,"multiple":4,"valuation":20.54,"bubble":"b2","totalRevenue":18.73,"logo_file":"logo_bhadepay.txt","logo":"assets/brand-images/bhadepay_logo_pay.jpg","founders":[{"name":"Prateek Chaudhari","photo":"data:image/jpeg;base64,"},{"name":"Mohammad Aslam","photo":"assets/founders/bhade_pay_aslam.jpg"}]},{"name":"Ecosys","key":"ecosys","short":"EC","fy25":1.95,"fy26":15.1,"fy27":20.196,"growth":33.75,"gm":53.4,"ebitda":-0.15,"ebitdaMargin":-1,"multiple":4,"valuation":60.4,"bubble":"b3","totalRevenue":37.246,"logo_file":"logo_ecosys.txt","logo":"assets/brand-images/ecosys.jpg","founders":[{"name":"Chirag Dangi","photo":"data:image/jpeg;base64,"},{"name":"Sumit Goyal","photo":"data:image/jpeg;base64,"}]},{"name":"Orionz","key":"orionz","short":"OZ","fy25":3.73,"fy26":5.52,"fy27":4.428,"growth":-19.78,"gm":69.1,"ebitda":0.13,"ebitdaMargin":2.3,"multiple":4,"valuation":22.08,"bubble":"b4","totalRevenue":13.678,"logo_file":"logo_orionz.txt","logo":"data:image/webp;base64,","founders":[{"name":"Alisha Jhaveri Shah","photo":"data:image/jpeg;base64,"},{"name":"Harsh Shah","photo":"data:image/jpeg;base64,"}]}];
    const byKey = Object.fromEntries(brands.map(b => [b.key, b]));
    const modal = document.getElementById('modal');
    const popCard = document.getElementById('popCard');
    const connector = document.getElementById('connector');
    const popClose = document.getElementById('popClose');
    const frameTag = document.getElementById('frameTag');
    let activeOrb = null;

    function money(n) { return '₹' + Number(n).toFixed(2) + ' Cr'; }
    function percent(n) { return Number(n).toFixed(2) + '%'; }
    function clamp(v, min, max) { return Math.min(Math.max(v, min), max); }

    function drawChart(b) {
      const svg = document.getElementById('popSvg');
      const values = [b.fy25, b.fy26, b.fy27];
      const labels = ['FY25', 'FY26', 'FY27 (Proj)'];
      const W = 320, H = 150, left = 32, right = 36, top = 16, bottom = 26;
      const plotW = W - left - right, plotH = H - top - bottom;
      const max = Math.max(...values) * 1.2 || 1;
      const x = i => left + i * (plotW / (values.length - 1));
      const y = v => top + plotH - (v / max) * plotH;
      let out = '';
      for (let i = 0; i <= 3; i++) {
        const v = max * i / 3, yy = y(v);
        out += `<line x1="${left}" y1="${yy}" x2="${W - right}" y2="${yy}" stroke="#3F7895" stroke-opacity="0.4" stroke-width="1"/>`;
      }
      const points = values.map((v, i) => `${x(i)},${y(v)}`).join(' ');
      const area = `${left},${top + plotH} ${points} ${W - right},${top + plotH}`;
      out += `<polygon points="${area}" fill="#F8D742" opacity=".14"/>`;
      out += `<polyline points="${points}" fill="none" stroke="#F8D742" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"/>`;
      values.forEach((v, i) => {
        out += `<circle cx="${x(i)}" cy="${y(v)}" r="4" fill="#F8D742" stroke="#18263D" stroke-width="2"/>`;
        out += `<text x="${x(i)}" y="${y(v) - 9}" text-anchor="middle" fill="#F6EADA" font-size="9" font-family="monospace">${v.toFixed(1)}</text>`;
        out += `<text x="${x(i)}" y="${H - 8}" text-anchor="middle" fill="#8FC4D4" font-size="9" font-family="monospace">${labels[i]}</text>`;
      });
      svg.innerHTML = out;
    }

    function positionCard() {
      if (!activeOrb || !modal.classList.contains('open')) return;
      const b = activeOrb.getBoundingClientRect();
      const gap = 18, pad = 12;
      const r = popCard.getBoundingClientRect();
      const fitsRight = b.right + gap + r.width <= window.innerWidth - pad;
      let left = fitsRight ? b.right + gap : b.left - r.width - gap;
      let top = b.top + b.height / 2 - r.height / 2;
      left = clamp(left, pad, Math.max(pad, window.innerWidth - r.width - pad));
      top = clamp(top, pad, Math.max(pad, window.innerHeight - r.height - pad));
      popCard.style.left = left + 'px'; popCard.style.top = top + 'px';
      const c = popCard.getBoundingClientRect();
      const y = b.top + b.height / 2;
      const sx = fitsRight ? b.right : c.right;
      const ex = fitsRight ? c.left : b.left;
      connector.style.left = Math.min(sx, ex) + 'px';
      connector.style.top = (y - 1) + 'px';
      connector.style.width = Math.abs(ex - sx) + 'px';
    }

    function openBrand(orb) {
      const b = byKey[orb.dataset.key];
      if (!b) return;
      document.querySelectorAll('.orb').forEach(o => o.classList.remove('active'));
      orb.classList.add('active');
      activeOrb = orb;
      document.getElementById('popLogo').src = b.logo;
      document.getElementById('popLogo').alt = b.name + ' logo';
      document.getElementById('popName').textContent = b.name;
      document.getElementById('popVal').textContent = money(b.valuation);
      document.getElementById('popRev').textContent = money(b.totalRevenue);
      const growthVal = (b.fy26 && b.fy27) ? (((b.fy27 - b.fy26) / b.fy26) * 100) : b.growth;
      document.getElementById('popGrowth').textContent = (growthVal !== undefined && growthVal !== null) ? percent(growthVal) : '0.00%';
      document.getElementById('popEbitda').textContent = (b.ebitdaMargin !== undefined && b.ebitdaMargin !== null) ? percent(b.ebitdaMargin) : '0.00%';
      document.getElementById('popNote').textContent = `FY25: ${money(b.fy25)} · FY26: ${money(b.fy26)} · FY27 (Proj): ${money(b.fy27)}`;
      const foundersHtml = (b.founders || []).map(f =>
        `<div class="founder"><img src="${f.photo}" alt="${f.name}"><span>${f.name}</span></div>`
      ).join('');
      document.getElementById('popFounders').innerHTML = foundersHtml;
      drawChart(b);
      modal.classList.add('open');
      requestAnimationFrame(positionCard);
    }

    document.querySelectorAll('.orb').forEach(el => {
      el.addEventListener('mouseenter', () => {
        const b = byKey[el.dataset.key];
        const r = el.getBoundingClientRect();
        document.getElementById('frameTagLogo').src = b.logo;
        document.getElementById('frameTagName').textContent = b.name;
        frameTag.style.left = (r.left - frameTag.parentElement.getBoundingClientRect().left) + 'px';
        frameTag.style.top = (r.top - frameTag.parentElement.getBoundingClientRect().top - 40) + 'px';
        frameTag.classList.add('show');
      });
      el.addEventListener('mouseleave', () => frameTag.classList.remove('show'));
      el.addEventListener('click', () => openBrand(el));
    });

    function closeModal() {
      modal.classList.remove('open');
      connector.style.width = '0px';
      document.querySelectorAll('.orb').forEach(o => o.classList.remove('active'));
      activeOrb = null;
    }
    popClose.addEventListener('click', closeModal);
    modal.addEventListener('click', e => { if (e.target === modal) closeModal(); });
    window.addEventListener('resize', positionCard);
    window.addEventListener('scroll', positionCard, { passive: true });
    document.addEventListener('keydown', e => { if (e.key === 'Escape') closeModal(); });

/* --- SECURITY & PASSCODE GATE CONTROLLER --- */
function setupSecurityGate() {
  const VALID_PASSWORDS = ['proteus', 'proteus2026', 'proteus123', 'partner', 'partners'];
  
  const gateOverlay = document.getElementById('gateOverlay');
  const gateForm = document.getElementById('gateForm');
  const gatePass = document.getElementById('gatePass');
  const eyeBtn = document.getElementById('eyeBtn');
  const gateError = document.getElementById('gateError');
  const gateCard = document.querySelector('.gate-card');
  const pageMain = document.querySelector('.page');
  const lockBtn = document.getElementById('lockBtn');
  const secToast = document.getElementById('secToast');

  function isUnlocked() {
    return sessionStorage.getItem('proteus_unlocked') === 'true';
  }

  function applyLockState() {
    if (isUnlocked()) {
      if (gateOverlay) {
        gateOverlay.classList.add('hidden');
        gateOverlay.style.display = 'none';
      }
      if (pageMain) pageMain.classList.remove('locked');
      document.body.style.overflow = '';
    } else {
      if (gateOverlay) {
        gateOverlay.classList.remove('hidden');
        gateOverlay.style.display = 'flex';
      }
      if (pageMain) pageMain.classList.add('locked');
      document.body.style.overflow = 'hidden';
      if (gatePass) setTimeout(() => gatePass.focus(), 200);
    }
  }

  // Initial check
  applyLockState();

  // Password toggle
  if (eyeBtn && gatePass) {
    eyeBtn.addEventListener('click', (e) => {
      e.preventDefault();
      const type = gatePass.getAttribute('type') === 'password' ? 'text' : 'password';
      gatePass.setAttribute('type', type);
      eyeBtn.textContent = type === 'password' ? '👁️' : '🙈';
    });
  }

  // Submit password
  if (gateForm) {
    gateForm.addEventListener('submit', (e) => {
      e.preventDefault();
      const inputVal = (gatePass ? gatePass.value : '').trim().toLowerCase();
      
      if (VALID_PASSWORDS.includes(inputVal)) {
        sessionStorage.setItem('proteus_unlocked', 'true');
        if (gateError) gateError.textContent = '';
        applyLockState();
        showSecToast('🔓 Access Granted. Portfolio Unlocked.');
      } else {
        if (gateError) gateError.textContent = '❌ Access Denied: Incorrect Password';
        if (gateCard) {
          gateCard.classList.remove('shake');
          void gateCard.offsetWidth; // trigger reflow
          gateCard.classList.add('shake');
        }
        if (gatePass) {
          gatePass.value = '';
          gatePass.focus();
        }
      }
    });
  }

  // Lock button in topbar
  if (lockBtn) {
    lockBtn.addEventListener('click', () => {
      sessionStorage.removeItem('proteus_unlocked');
      applyLockState();
      showSecToast('🔒 Portfolio Locked.');
    });
  }

  // Security Toast Trigger
  let toastTimer = null;
  function showSecToast(msg) {
    if (!secToast) return;
    secToast.textContent = msg;
    secToast.classList.add('show');
    clearTimeout(toastTimer);
    toastTimer = setTimeout(() => {
      secToast.classList.remove('show');
    }, 3200);
  }

  /* --- ANTI-INSPECTION & SHORTCUT PROTECTIONS --- */

  // 1. Disable Right Click Context Menu
  document.addEventListener('contextmenu', (e) => {
    e.preventDefault();
    showSecToast('🔒 Security Notice: Right-click context menu is disabled.');
    return false;
  });

  // 2. Disable DevTools Keyboard Shortcuts
  document.addEventListener('keydown', (e) => {
    // F12 key
    if (e.keyCode === 123) {
      e.preventDefault();
      showSecToast('🔒 Security Notice: F12 inspection shortcut is disabled.');
      return false;
    }
    // Ctrl+Shift+I, Ctrl+Shift+J, Ctrl+Shift+C
    if (e.ctrlKey && e.shiftKey && (e.keyCode === 73 || e.keyCode === 74 || e.keyCode === 67)) {
      e.preventDefault();
      showSecToast('🔒 Security Notice: DevTools inspection shortcuts are disabled.');
      return false;
    }
    // Ctrl+U (View Source)
    if (e.ctrlKey && e.keyCode === 85) {
      e.preventDefault();
      showSecToast('🔒 Security Notice: View Source is disabled.');
      return false;
    }
    // Ctrl+S (Save Page)
    if (e.ctrlKey && e.keyCode === 83) {
      e.preventDefault();
      showSecToast('🔒 Security Notice: Saving page is disabled.');
      return false;
    }
  });
}

if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', setupSecurityGate);
} else {
  setupSecurityGate();
}

